import{_ as r,y as i,a as s,o as a,a2 as t,D as o}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Invoice Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configure/invoice-settings.md","filePath":"configure/invoice-settings.md","lastUpdated":1789441803000}'),d={name:"configure/invoice-settings.md"};function h(c,e,l,g,m,u){const n=i("ImagePopup");return a(),s("div",null,[e[0]||(e[0]=t('<h1 id="invoice-settings" tabindex="-1">Invoice Settings <a class="header-anchor" href="#invoice-settings" aria-label="Permalink to &quot;Invoice Settings&quot;">​</a></h1><p>These settings decide how invoice numbers are built, when invoices are due, what the invoice PDF shows, and how reminders are sent for overdue invoices. How invoices are created is described in <a href="./../orders/create-invoice.html">Create Invoice</a>, and payments for pending invoices are recorded in <a href="./../orders/transactions.html">Transactions</a>.</p><h2 id="invoice-numbers" tabindex="-1">Invoice numbers <a class="header-anchor" href="#invoice-numbers" aria-label="Permalink to &quot;Invoice numbers&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Invoice Settings</strong>.</li><li>If your store has more than one channel or language, choose them at the top of the screen.</li><li>In <strong>Invoice Number Settings</strong>, fill in the settings described below.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),o(n,{src:"/images/configure/invoice-settings-numbers.png",alt:"Invoice Number Settings and Payment Terms sections of the Invoice Settings screen"}),e[1]||(e[1]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Invoice Number Prefix</strong></td><td>Text at the start of every invoice number, such as <code>INV-</code>.</td></tr><tr><td><strong>Invoice Number Length</strong></td><td>How many digits the running number is padded to with zeros, from <code>0</code> to <code>10</code>.</td></tr><tr><td><strong>Invoice Number Suffix</strong></td><td>Text at the end of every invoice number.</td></tr><tr><td><strong>Invoice Number Generator</strong></td><td>Leave it empty unless a developer has built a custom number generator for your store.</td></tr></tbody></table><p>With a prefix of <code>INV-</code> and a length of <code>6</code>, invoices are numbered like <code>INV-000042</code>. The running number continues from the last invoice in the store, so a change here affects new invoices only. These settings are per channel and per language.</p><h2 id="payment-terms" tabindex="-1">Payment terms <a class="header-anchor" href="#payment-terms" aria-label="Permalink to &quot;Payment terms&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Invoice Settings</strong>.</li><li>If your store has more than one channel, choose the channel at the top of the screen.</li><li>In <strong>Payment Terms</strong>, enter the <strong>Due Duration</strong>, the number of days customers have to pay an invoice.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The due date of an invoice is its invoice date plus the due duration. The invoice list under <strong>Sales &gt;&gt; Invoices</strong> shows how many days are left until the due date, or how long an invoice is overdue; see <a href="./../orders/create-invoice.html#invoice-status">Invoice status</a>. When the due duration is more than <code>0</code>, the invoice PDF also shows the payment terms in days. The due duration is per channel.</p><h2 id="pdf-print-outs" tabindex="-1">PDF print outs <a class="header-anchor" href="#pdf-print-outs" aria-label="Permalink to &quot;PDF print outs&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Invoice Settings</strong>.</li><li>If your store has more than one channel or language, choose them at the top of the screen.</li><li>In <strong>PDF Print Outs</strong>, switch <strong>Display Invoice ID in Header</strong> on or off.</li><li>Switch <strong>Display Order ID in Header</strong> on or off.</li><li>Under <strong>Logo</strong>, click <strong>Add Image</strong>.</li><li>Choose the logo to print on the invoice.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',7)),o(n,{src:"/images/configure/invoice-settings-pdf.png",alt:"PDF Print Outs and Invoice Reminders sections of the Invoice Settings screen"}),e[2]||(e[2]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Display Invoice ID in Header</strong></td><td>Prints the invoice ID at the top of the PDF. It&#39;s on in a new store.</td></tr><tr><td><strong>Display Order ID in Header</strong></td><td>Prints the order ID at the top of the PDF. It&#39;s on in a new store.</td></tr><tr><td><strong>Logo</strong></td><td>The logo printed on the PDF. A size of 131 × 30 pixels is recommended.</td></tr><tr><td><strong>Footer text</strong></td><td>Saved with these settings, but not printed on the invoice PDF.</td></tr></tbody></table><p>The same PDF is used when you <a href="./../orders/create-invoice.html#print-an-invoice">print an invoice</a> in the admin panel, when customers download it from their account, and when it&#39;s attached to the invoice email. The two switches apply to the whole store. The logo is per channel, and the footer text is per channel and per language.</p><h2 id="invoice-reminders" tabindex="-1">Invoice reminders <a class="header-anchor" href="#invoice-reminders" aria-label="Permalink to &quot;Invoice reminders&quot;">​</a></h2><p>Once a day, the store sends a reminder email for each invoice that is marked <strong>Overdue</strong>. The reminders go to the <strong>Sender Email Address</strong> set in <a href="./email-settings.html#email-settings">Email Settings</a>, not to the customer.</p><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Invoice Settings</strong>.</li><li>If your store has more than one channel, choose the default channel at the top of the screen.</li><li>In <strong>Invoice Reminders</strong>, enter the <strong>Maximum limit of reminders</strong> sent for one invoice.</li><li>Choose the <strong>Interval between reminders</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p><strong>Maximum limit of reminders:</strong> How many reminders are sent for one invoice. Leave it empty, or enter <code>0</code>, for no limit. The maximum set for the default channel applies to invoices from every channel.</p><p><strong>Interval between reminders:</strong> How long the store waits after one reminder before it sends the next. Choose from <strong>1 day</strong> to <strong>4 days</strong>, or <strong>2 weeks</strong> to <strong>4 weeks</strong>: <strong>5 days</strong>, <strong>6 days</strong> and <strong>7 days</strong> are currently saved as <strong>4 days</strong>. The interval applies to the whole store.</p><p>To mark invoices as overdue:</p><ol><li>Go to <strong>Sales &gt;&gt; Invoices</strong>.</li><li>Select the invoices.</li><li>Click <strong>Select Action &gt;&gt; Update Status &gt;&gt; Overdue</strong>.</li></ol><p>See <a href="./../orders/create-invoice.html#change-the-status-of-invoices">Change the status of invoices</a>.</p><h3 id="reminders-need-the-server-s-scheduler" tabindex="-1">Reminders need the server&#39;s scheduler <a class="header-anchor" href="#reminders-need-the-server-s-scheduler" aria-label="Permalink to &quot;Reminders need the server&#39;s scheduler&quot;">​</a></h3><p>Reminders are sent by the server&#39;s task scheduler and email queue. If they aren&#39;t sent, ask whoever manages your server to check that both are running. See <a href="./../getting-started/scheduled-tasks.html">Scheduled Tasks</a>.</p>',12))])}const p=r(d,[["render",h]]);export{f as __pageData,p as default};
